  const pos = new Map();
  nums.forEach((v, i) => pos.set(v, i));
  const out = nums.slice();
  for (const op of operations) {
    const idx = pos.get(op[0]);
    out[idx] = op[1];
    pos.delete(op[0]);
    pos.set(op[1], idx);
  }
  return out;
}
